import hashlib, json
import pyarrow.parquet as pq

def canonical(value):
    return json.dumps(value, ensure_ascii=False, sort_keys=True,
                      separators=(",", ":"), allow_nan=False)

def semantic_row(row):
    row = {k: v for k, v in row.items()
           if k not in {"id", "human_readable_id"}}
    if row.get("text_unit_ids") is not None:
        row["text_unit_ids"] = sorted(row["text_unit_ids"])
    return row

def row_sha256(row):
    return hashlib.sha256(canonical(semantic_row(row)).encode("utf-8")).hexdigest()

def table_sha256(parquet_path):
    rows = pq.read_table(parquet_path).to_pylist()
    serialized = sorted(canonical(semantic_row(row)) for row in rows)
    return hashlib.sha256(canonical(serialized).encode("utf-8")).hexdigest()

